  "test_path": "tests/unit/test_observe_error_capture.py",
  "test": "import pytest
from langfuse._client.observe import LangfuseDecorator
from langfuse._client.observe import _ContextPreservedSyncGeneratorWrapper  # noqa: F401
from langfuse._client.observe import _ContextPreservedAsyncGeneratorWrapper  # noqa: F401
from langfuse._client.observe import get_client
from typing import Any

class DummyContextManager:
    def __init__(self, recorder):
        self.recorder = recorder
    def __enter__(self):
        return self.recorder
    def __exit__(self, exc_type, exc, tb):
        self.recorder.end()
        # Do not suppress exceptions
        return False

class DummyAsyncContextManager:
    def __init__(self, recorder):
        self.recorder = recorder
    async def __aenter__(self):
        return self.recorder
    async def __aexit__(self, exc_type, exc, tb):
        self.recorder.end()
        return False

class DummyClient:
    def __init__(self, recorder, async_mode=False):
        self.recorder = recorder
        self.async_mode = async_mode
    def start_as_current_observation(self, *args, **kwargs):
        if self.async_mode:
            return DummyAsyncContextManager(self.recorder)
        return DummyContextManager(self.recorder)


def test_observe_defaults_capture_error(monkeypatch):
    recorder = SpanRecorder()
    dummy = DummyClient(recorder)
    monkeypatch.setattr('langfuse._client.observe.get_client', lambda *a, **k: dummy)
    decorator = LangfuseDecorator()
    @decorator.observe()
    def fail():
        raise ValueError("boom")
    with pytest.raises(ValueError):
        fail()
    # Since capture_error defaults to True, an update with level ERROR should be recorded
    assert any(update.get("level") == "ERROR" for update in recorder.updates)


def test_observe_capture_error_false(monkeypatch):
    recorder = SpanRecorder()
    dummy = DummyClient(recorder)
    monkeypatch.setattr('langfuse._client.observe.get_client', lambda *a, **k: dummy)
    decorator = LangfuseDecorator()
    @decorator.observe(capture_error=False)
    def fail():
        raise RuntimeError("uh oh")
    with pytest.raises(RuntimeError):
        fail()
    # No error level update should be recorded when capture_error=False
    assert all(update.get("level") != "ERROR" for update in recorder.updates)
